$:set -euo pipefail
echo "HEAD $(git rev-parse HEAD)"
echo '=== SOURCE COMMITS ==='
git log -5 --format='%h %s' | head -5
echo '=== FILES AND ARCHIVE ==='
for file in workspaces/programs/scratchpad/scratchpad-core.js workspaces/programs/scratchpad/scratchpad.js workspaces/programs/scratchpad/SRS.md workspaces/programs/scratchpad/SRS.agent.json workspaces/programs/selection-template.tmpl workspaces/programs/selection-element-specification.md workspaces/programs/versions/v0.2.0/selection-template.tmpl workspaces/programs/versions/v0.2.0/selection-element-specification.md; do test -f "$file" || exit 1; echo "PRESENT $file"; done
echo '=== EXECUTABLE ASSERTIONS ==='
node - <<'NODE'
const assert=require('node:assert/strict');
const c=require('./workspaces/programs/scratchpad/scratchpad-core.js');
const app=require('./workspaces/programs/scratchpad/scratchpad.js');
const d=c.makeDoc({issue:4,task_id:'verification',topic:'Test',agent_nonce:'verify',work:'initial',now:'2026-11-05T10:00:00Z'});
const out=app.entryMenu(123,d);
assert.equal(d.header.entry_count,1);
assert.equal(out.menu.comment.entry_count,1);
assert.equal(out.menu.selection.options.length,2);
assert.deepEqual(out.menu.selection.goto,[{'main-menu':[['Main'],['Back']]}]);
assert.equal(c.append(d,{work:'next',now:'2026-11-05T10:00:01Z'}).header.entry_count,2);
console.log('VERIFIED DATA COUNT AND GOTO');
NODE
python3 - <<'PY'
import json
from pathlib import Path
x=json.loads(Path('workspaces/programs/scratchpad/SRS.agent.json').read_text())
assert x['version']=='1.3.0'
assert {'SP-19','SP-20'}<= {r['id'] for r in x['requirements']}
t=Path('workspaces/programs/selection-template.tmpl').read_text()
assert '"goto": <goto>' in t
assert '"version": "0.3.0"' in t
print('VERIFIED SPEC PROJECTION AND TEMPLATE')
PY
